signal dog

var hp := 100

func _ready():
	dog.connect(_on_dog)
	for i in range(3):
		ta_skada(40)

func ta_skada(n: int):
	hp = max(hp - n, 0)
	print("HP ", hp)
	if hp <= 0:
		dog.emit()

func _on_dog():
	print("Game over")

extends Node2D

signal vann

var mynt := [Vector2(50, 0), Vector2(100, 0), Vector2(150, 0)]
var poang := 0
var klar := false

func _ready():
	vann.connect(_on_vann)

func _process(delta):
	position.x += Input.get_axis("ui_left", "ui_right") * 120 * delta
	for i in range(mynt.size() - 1, -1, -1):
		if position.distance_to(mynt[i]) < 16:
			mynt.remove_at(i)
			poang += 1
			print("Mynt! Poäng: ", poang)
	if mynt.is_empty() and not klar:
		klar = true
		vann.emit()

func _on_vann():
	print("Du vann!")

extends Node2D

var fiende := Node2D.new()
var tid := 0.0
var fangad := false

func _ready():
	fiende.position = Vector2(200, 0)
	add_child(fiende)

func _process(delta):
	if fangad:
		return
	tid += delta
	fiende.position = fiende.position.move_toward(Vector2.ZERO, 60 * delta)
	if fiende.position.distance_to(Vector2.ZERO) < 10:
		fangad = true
		print("Fångad! %.1f s" % tid)
